/* Generated by prepare-pos-worker.mjs before every production build.
   Only the public training shell and its static assets enter this cache.
   Authenticated routes, API responses, receipts and customer records never do. */
const VERSION = '20261016040643589-8b091ec7';
const CACHE_PREFIX = 'internext-pos-shell-';
const CACHE = `${CACHE_PREFIX}${VERSION}`;
const SHELL = '/pos';
const COMPLETE = '/pos-offline-complete';
const isStatic = pathname => pathname.startsWith('/_next/static/') || pathname.startsWith('/pos-assets/') || pathname === '/pos.webmanifest' || pathname === '/pos-icon.svg';

function staticPath(value, base = self.location.origin) {
  try {
    const url = new URL(value.replaceAll('&amp;', '&'), base);
    return url.origin === self.location.origin && isStatic(url.pathname) ? `${url.pathname}${url.search}` : null;
  } catch { return null; }
}
async function tellClients(message) {
  const clients = await self.clients.matchAll({ type: 'window', includeUncontrolled: true });
  for (const client of clients) if (new URL(client.url).pathname.startsWith('/pos')) client.postMessage(message);
}

self.addEventListener('install', event => {
  event.waitUntil((async () => {
    // Every build has its own namespace. Installation never mutates the active
    // version's shell, chunks or readiness marker, even if this download fails.
    const cache = await caches.open(CACHE);
    const fetched = new Set();
    let totalBytes = 0;
    async function download(path) {
      if (fetched.has(path)) return null;
      fetched.add(path);
      const response = await fetch(path, { cache: 'reload', credentials: 'same-origin' });
      if (!response.ok || response.type === 'opaque') throw new Error(`Offline download failed: ${path}`);
      totalBytes += (await response.clone().arrayBuffer()).byteLength;
      if (totalBytes > 100_000_000) throw new Error('Offline app download exceeded its storage budget.');
      await cache.put(path, response.clone());
      return response;
    }
    try {
      const shell = await download(SHELL);
      if (!shell || !shell.headers.get('content-type')?.includes('text/html')) throw new Error('The offline app shell was not available.');
      const html = await shell.text();
      const paths = [...new Set([...html.matchAll(/(?:src|href)=["']([^"'\s]+)["']/g)].map(match => staticPath(match[1])).filter(Boolean))];
      if (!paths.some(path => path.startsWith('/_next/static/'))) throw new Error('The offline app shell did not include its required application files.');
      const manifest = await download('/pos-assets/offline-assets.json');
      const images = await manifest.json();
      if (!Array.isArray(images) || images.length > 2000 || images.some(path => typeof path !== 'string' || !path.startsWith('/pos-assets/') || !staticPath(path))) throw new Error('The offline image manifest is invalid.');
      const queue = [...new Set([...paths, ...images, '/pos.webmanifest', '/pos-icon.svg'])];
      // CSS can reference locally bundled fonts/images absent from HTML. Follow
      // those static references too before claiming the installation is ready.
      for (let index = 0; index < queue.length;) {
        const batch = queue.slice(index, index + 6);
        index += batch.length;
        await Promise.all(batch.map(async path => {
          const response = await download(path);
          if (!response) return;
          if (response.headers.get('content-type')?.includes('text/css') || new URL(path, self.location.origin).pathname.endsWith('.css')) {
            const css = await response.text();
            const references = [...css.matchAll(/url\(\s*["']?([^"')\s]+)["']?\s*\)|@import\s+["']([^"']+)["']/g)];
            for (const match of references) {
              const dependency = staticPath(match[1] || match[2], new URL(path, self.location.origin).href);
              if (dependency && !queue.includes(dependency)) queue.push(dependency);
            }
          }
        }));
      }
      await cache.put(COMPLETE, new Response(JSON.stringify({ version: VERSION, assets: fetched.size, bytes: totalBytes }), { headers: { 'Content-Type': 'application/json' } }));
      await tellClients({ type: 'POS_OFFLINE_UPDATE_DOWNLOADED', version: VERSION });
      // No skipWaiting: activation waits until the previous version's tabs close.
    } catch (error) {
      await caches.delete(CACHE);
      await tellClients({ type: 'POS_OFFLINE_FAILED', message: 'Offline app download failed. Keep this device online and retry the download.' });
      throw error;
    }
  })());
});

self.addEventListener('activate', event => {
  event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    if (!await cache.match(COMPLETE)) throw new Error('Refusing to activate an incomplete offline app.');
    for (const key of await caches.keys()) if (key.startsWith(CACHE_PREFIX) && key !== CACHE) await caches.delete(key);
    await self.clients.claim();
    await tellClients({ type: 'POS_OFFLINE_READY', version: VERSION });
  })());
});

self.addEventListener('message', event => {
  if (event.data?.type === 'CHECK_POS_CACHE') event.waitUntil((async () => {
    const cache = await caches.open(CACHE);
    if (await cache.match(COMPLETE)) event.source?.postMessage({ type: 'POS_OFFLINE_READY', version: VERSION });
    else event.source?.postMessage({ type: 'POS_OFFLINE_FAILED', message: 'The offline app download is incomplete. Keep this device online and retry.' });
  })());
});

self.addEventListener('fetch', event => {
  const request = event.request;
  const url = new URL(request.url);
  if (request.method !== 'GET' || url.origin !== self.location.origin || url.pathname.startsWith('/api/')) return;
  if (request.mode === 'navigate' && (url.pathname === '/pos' || url.pathname === '/pos/')) {
    event.respondWith((async () => {
      const cache = await caches.open(CACHE);
      const cached = await cache.match(SHELL);
      return cached || fetch(request);
    })());
  } else if (isStatic(url.pathname)) {
    event.respondWith((async () => {
      const cache = await caches.open(CACHE);
      const cached = await cache.match(request);
      if (cached) return cached;
      const response = await fetch(request);
      if (response.ok && response.type !== 'opaque') await cache.put(request, response.clone());
      return response;
    })());
  }
});
